#!/usr/bin/env bash
# Tool: Claude Code (agent, Claude Opus 5.5)
# This runner and the cases in tests/e2e/cases were generated by the agent from the IFJ26
# specification, without using the implementation; reviewed by us.
# End-to-end tests derived from the IFJ26 specification. A case is tests/e2e/cases/<category>/<name>.ifj
# with a header "//! compile: N" (and "//! run: N" if it compiles), optional <name>.in as stdin and
# <name>.expected as the exact expected stdout.
#
# Usage: tests/e2e/run.sh [-v] [filter ...]
#   -v        show the compiler/interpreter stderr and the output diff of failing cases
#   filter    run only cases whose path contains one of the given strings (e.g. 03_semantic, e6_)
#
# Environment:
#   COMPILER  compiler executable (default: ./compiler in the repository root, built with "make build")
#   IC26INT   IFJcode26 interpreter (default: ic26int from PATH); without it only the compiler's
#             exit codes are checked and running the generated code is skipped
#   TIMEOUT   seconds per compiler or interpreter run (default: 10)

set -u

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
CASES="$ROOT/tests/e2e/cases"
COMPILER="${COMPILER:-$ROOT/compiler}"
IC26INT="${IC26INT:-ic26int}"
TIMEOUT="${TIMEOUT:-10}"
VERBOSE=0
FILTERS=()

for arg in "$@"; do
	case "$arg" in
	-v) VERBOSE=1 ;;
	-h | --help)
		sed -n '5,18p' "$0"
		exit 0
		;;
	*) FILTERS+=("$arg") ;;
	esac
done

if [ ! -x "$COMPILER" ]; then
	echo "Building the compiler (make build) ..."
	(cd "$ROOT" && make build >/dev/null) || {
		echo "error: the compiler could not be built" >&2
		exit 2
	}
fi

HAVE_INTERPRETER=0
if command -v "$IC26INT" >/dev/null 2>&1; then
	HAVE_INTERPRETER=1
else
	echo "note: interpreter '$IC26INT' not found, generated code is not executed (set IC26INT)"
fi

WORK="$(mktemp -d)"
trap 'rm -rf "$WORK"' EXIT

# expectation <file> <key> <default>: value of a "//! key: value" header line
expectation() {
	local value
	value="$(sed -n "s|^//! $2: *||p" "$1" | head -n 1)"
	echo "${value:-$3}"
}

matches_filter() {
	[ "${#FILTERS[@]}" -eq 0 ] && return 0
	local f
	for f in "${FILTERS[@]}"; do
		case "$1" in *"$f"*) return 0 ;; esac
	done
	return 1
}

show() {
	[ "$VERBOSE" -eq 1 ] && [ -s "$1" ] && sed 's/^/        /' "$1" | head -n 15
}

pass=0
fail=0
run_skipped=0
declare -A cat_pass cat_fail
failed_cases=()

while IFS= read -r src; do
	rel="${src#"$CASES"/}"
	matches_filter "$rel" || continue
	cat="${rel%%/*}"
	base="${src%.ifj}"
	exp_compile="$(expectation "$src" compile 0)"
	exp_run="$(expectation "$src" run 0)"

	# the "//!" header is not part of the program
	grep -v '^//!' "$src" >"$WORK/prog.ifj"

	timeout "$TIMEOUT" "$COMPILER" <"$WORK/prog.ifj" >"$WORK/prog.code" 2>"$WORK/compile.err"
	got_compile=$?

	status=PASS
	detail=""
	if [ "$got_compile" -ne "$exp_compile" ]; then
		status=FAIL
		detail="compiler exit code $got_compile, expected $exp_compile"
	elif [ "$exp_compile" -eq 0 ]; then
		if [ "$HAVE_INTERPRETER" -eq 0 ]; then
			detail="compiled, not executed"
			run_skipped=$((run_skipped + 1))
		else
			input=/dev/null
			[ -f "$base.in" ] && input="$base.in"
			timeout "$TIMEOUT" "$IC26INT" "$WORK/prog.code" <"$input" >"$WORK/prog.stdout" 2>"$WORK/run.err"
			got_run=$?
			if [ "$got_run" -ne "$exp_run" ]; then
				status=FAIL
				detail="interpreter exit code $got_run, expected $exp_run"
			elif [ -f "$base.expected" ] && ! cmp -s "$WORK/prog.stdout" "$base.expected"; then
				status=FAIL
				detail="output differs from $(basename "$base").expected"
			fi
		fi
	fi

	if [ "$status" = PASS ]; then
		pass=$((pass + 1))
		cat_pass[$cat]=$((${cat_pass[$cat]:-0} + 1))
		[ "$VERBOSE" -eq 1 ] && printf 'PASS  %s%s\n' "$rel" "${detail:+  ($detail)}"
	else
		fail=$((fail + 1))
		cat_fail[$cat]=$((${cat_fail[$cat]:-0} + 1))
		failed_cases+=("$rel: $detail")
		printf 'FAIL  %s  (%s)\n' "$rel" "$detail"
		show "$WORK/compile.err"
		if [ "$VERBOSE" -eq 1 ] && [ -f "$WORK/prog.stdout" ] && [ -f "$base.expected" ]; then
			diff <(cat "$base.expected") "$WORK/prog.stdout" | sed 's/^/        /' | head -n 15
		fi
	fi
	rm -f "$WORK/prog.stdout"
done < <(find "$CASES" -name '*.ifj' | sort)

echo
printf '%-20s %6s %6s\n' "category" "pass" "fail"
for cat in $(printf '%s\n' "${!cat_pass[@]}" "${!cat_fail[@]}" | sort -u); do
	printf '%-20s %6s %6s\n' "$cat" "${cat_pass[$cat]:-0}" "${cat_fail[$cat]:-0}"
done
echo
echo "passed: $pass, failed: $fail$([ "$run_skipped" -gt 0 ] && echo ", run skipped (no interpreter): $run_skipped")"
[ "$fail" -eq 0 ]
